'use strict';
(()=>{
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const names={outil:'Outil',prompt:'Prompt',tutoriel:'Tutoriel',scenario:'Scénario',guide:'Guide',concept:'Concept',source:'Source'};
let toastTimer;function toast(text){$('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',4200)}
function get(key,fallback=[]){try{return JSON.parse(localStorage.getItem('manar:'+key))??fallback}catch{return fallback}}
function set(key,value){try{localStorage.setItem('manar:'+key,JSON.stringify(value));return true}catch{toast('Stockage indisponible : cette modification ne peut pas être conservée.');return false}}
function array(key){const v=get(key);return Array.isArray(v)?v.filter(x=>typeof x==='string'):[]}
let favorites=new Set(array('favorites')),comparison=new Set(array('comparison'));
const bookmark=`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h14v19l-7-5-7 5Z"/></svg>`;
function card(r){const picked=favorites.has(r.id);return `<article class="card"><div class="card-top"><span class="badge ${r.type}">${names[r.type]}</span><button class="bookmark" data-fav="${E(r.id)}" aria-label="${picked?'Retirer des':'Ajouter aux'} favoris : ${E(r.title)}" aria-pressed="${picked}">${bookmark}</button></div><h3><a href="/ressources/${r.id}/">${E(r.title)}</a></h3><p>${E(r.desc)}</p><div class="card-foot"><span>${E(r.discipline)} · ${E(r.difficulty)}</span><a class="arrow" href="/ressources/${r.id}/" aria-label="Lire ${E(r.title)}">↗</a></div>${r.type==='outil'?`<label class="comparison-select"><input type="checkbox" data-compare="${r.id}" ${comparison.has(r.id)?'checked':''}> Comparer cet outil</label>`:''}</article>`}
function syncFavorites(){for(const b of $$('[data-fav]')){const picked=favorites.has(b.dataset.fav);b.setAttribute('aria-pressed',String(picked));if(!b.classList.contains('bookmark'))b.innerHTML=bookmark+' '+(picked?'Retirer des favoris':'Ajouter aux favoris');else{const title=b.closest('.card')?.querySelector('h3')?.textContent||'';b.setAttribute('aria-label',(picked?'Retirer des':'Ajouter aux')+' favoris : '+title)}}}
function syncCompare(){if($('#compare-count'))$('#compare-count').textContent=`(${comparison.size})`}
document.addEventListener('click',async event=>{const fav=event.target.closest('[data-fav]');if(fav){const next=new Set(favorites),id=fav.dataset.fav;next.has(id)?next.delete(id):next.add(id);if(set('favorites',[...next])){favorites=next;syncFavorites();if($('#catalogue')?.dataset.type==='favorite')render();toast(favorites.has(id)?'Ressource ajoutée aux favoris.':'Ressource retirée des favoris.')}}if(event.target.closest('[data-print]'))window.print();if(event.target.closest('[data-share]')){try{if(navigator.share)await navigator.share({title:document.title,url:location.href});else await copy(location.href,'Lien copié.')}catch(e){if(e.name!=='AbortError')toast('Partage indisponible. Copiez l’adresse de la page.')}}});
document.addEventListener('change',event=>{const b=event.target.closest('[data-compare]');if(!b)return;if(b.checked&&comparison.size>=3){b.checked=false;toast('Vous pouvez comparer trois outils à la fois.');return}const next=new Set(comparison);b.checked?next.add(b.dataset.compare):next.delete(b.dataset.compare);if(set('comparison',[...next])){comparison=next;syncCompare()}else b.checked=comparison.has(b.dataset.compare)});
async function copy(text,message='Prompt copié.'){try{await navigator.clipboard.writeText(text);toast(message)}catch{const pre=$('#prompt-text');if(pre){const range=document.createRange();range.selectNodeContents(pre);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('Copie automatique indisponible : texte sélectionné, utilisez Copier.')}else toast('Copie indisponible : sélectionnez l’adresse dans votre navigateur.')}}
$('#copy-prompt')?.addEventListener('click',()=>copy($('#prompt-text').textContent));
const originalPrompt=$('#prompt-text')?.dataset.original;
function personalize(){if(!originalPrompt)return;let value=originalPrompt;for(const f of $$('[data-variable]'))if(f.value.trim())value=value.split(f.dataset.variable).join(f.value.trim());$('#prompt-text').textContent=value}
for(const input of $$('[data-variable]'))input.addEventListener('input',personalize);
$('#reset-prompt')?.addEventListener('click',()=>{$$('[data-variable]').forEach(i=>i.value='');personalize();toast('Variables réinitialisées.')});
const narrow=matchMedia('(max-width:760px)');function syncRail(){const closed=narrow.matches&&!$('#rail').classList.contains('open');$('#rail').inert=closed;$('#rail').setAttribute('aria-hidden',String(closed))}syncRail();narrow.addEventListener('change',syncRail);
function toggleMenu(close=false){const open=close?false:!$('#rail').classList.contains('open');$('#rail').classList.toggle('open',open);$('#shade').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));syncRail();if(open)$('#rail .nav a').focus()}
$('#menu')?.addEventListener('click',()=>toggleMenu());$('#shade')?.addEventListener('click',()=>toggleMenu(true));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#rail').classList.contains('open')){toggleMenu(true);$('#menu').focus()}});
const journey=$('[data-journey]');if(journey){const key='journey:'+journey.dataset.journey;let progress=new Set(array(key));const update=()=>{const boxes=$$('[data-completed]');boxes.forEach(i=>i.checked=progress.has(i.dataset.completed));const n=boxes.filter(i=>i.checked).length;$('#journey-progress').value=n;$('#journey-count').textContent=`— ${n} / ${boxes.length}`};update();for(const input of $$('[data-completed]'))input.addEventListener('change',()=>{const next=new Set(progress);input.checked?next.add(input.dataset.completed):next.delete(input.dataset.completed);if(set(key,[...next]))progress=next;update()});$('#reset-journey').addEventListener('click',()=>{if(set(key,[])){progress.clear();update();toast('Progression réinitialisée.')}})}
$('#glossary-query')?.addEventListener('input',event=>{const q=norm(event.target.value);let n=0;for(const el of $$('[data-term]')){el.hidden=!norm(el.dataset.term).includes(q);if(!el.hidden)n++}$('#glossary-count').textContent=n?`${n} terme${n>1?'s':''}`:'Aucun terme trouvé. Essayez un mot plus court.'});
const activeResource=$('[data-resource]')?.dataset.resource;if(activeResource)set('history',[activeResource,...array('history').filter(x=>x!==activeResource)].slice(0,20));
function download(data,name,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#contribution-form')?.addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const values=Object.fromEntries(new FormData(e.target));download({date:new Date().toISOString(),...values},'contribution-manar.json');$('#contribution-status').textContent='Votre fichier a été préparé pour téléchargement. Aucun message n’a été envoyé.'});
if($('#contribution-form')){const params=new URLSearchParams(location.search);for(const key of ['ressource','type']){const value=params.get(key);if(value&&$('#contribution-form').elements[key])$('#contribution-form').elements[key].value=value}}
$('#clear-local')?.addEventListener('click',()=>{if(!confirm('Effacer favoris, historique, comparaisons, progressions, prompts sauvegardés, collections et préférences SCOLAR·IA sur cet appareil ? Exportez votre espace avant de confirmer.'))return;try{Object.keys(localStorage).filter(k=>k.startsWith('manar:')||k.startsWith('scolaria:')).forEach(k=>localStorage.removeItem(k));favorites.clear();comparison.clear();syncFavorites();toast('Données locales SCOLAR·IA effacées.')}catch{toast('Impossible d’accéder au stockage du navigateur.')}});
let catalogue=[],page=1;const pageSize=12,params=new URLSearchParams(location.search);
const baseType=$('#catalogue')?.dataset.type||'';
const fields=['type','discipline','level','category','difficulty','language','cost','media','duration','status','audience','tool','accountAccess','studentAccess','toolKind','useCase','privacyLevel','learningTime','provider','verifiedYear'];
const synonyms={cours:'preparation',evaluer:'evaluation',quiz:'evaluation',eleves:'eleves',supports:'supports',arabe:'arabe',pdf:'document',seconde:'tronc commun'};
function matchesLevel(r,value){if(!value)return true;return r.level==='Collège et lycée'||r.level===value||r.level==='Collège'&&value.includes('collège')||r.level==='Lycée'&&(value.includes('baccalauréat')||value==='Tronc commun')}
function searchTerms(r,q){if(window.ScolariaSearch)return ScolariaSearch.matches(r,q);const hay=norm([r.title,r.desc,r.category,r.discipline,r.example,r.text,...(r.tags||[])].join(' '));return norm(q).trim().split(/\s+/).filter(Boolean).every(w=>hay.includes(w)||synonyms[w]&&hay.includes(synonyms[w]))}
function filtered(){const q=$('#query')?.value||'';return catalogue.filter(r=>{if(baseType==='favorite'&&!favorites.has(r.id))return false;if(baseType&&baseType!=='favorite'&&r.type!==baseType)return false;if(!searchTerms(r,q))return false;return fields.every(key=>{const value=$(`[data-filter="${key}"]`)?.value;if(!value)return true;if(key==='verifiedYear')return r.verifiedAt?.slice(0,4)===value;if(key==='useCase')return (r.skills||[]).includes(value);if(key==='privacyLevel')return r.privacyLevel==='unknown';if(key==='learningTime'){if(value==='Moins de 60 min')return r.minutes>0&&r.minutes<60;if(value==='60 min et plus')return r.minutes>=60;return r.minutes===parseInt(value,10)}if(key==='language'&&value!=='À vérifier')return (r.languages||[]).includes({Français:'fr',Arabe:'ar',Anglais:'en'}[value]);if(key==='level')return matchesLevel(r,value);if(key==='discipline')return r.discipline===value||r.discipline==='Toutes disciplines'||r.discipline==='Langues'&&['Français','Arabe','Anglais'].includes(value)||r.discipline==='Sciences'&&['SVT','Physique-chimie'].includes(value);if(key==='duration')return r.type==='scenario'&&(value==='Moins de 60 min'?r.minutes<60:r.minutes>=60);return r[key]===value})}).sort((a,b)=>{return window.ScolariaSearch?ScolariaSearch.score(b,q)-ScolariaSearch.score(a,q):0})}
function updateURL(){const p=new URLSearchParams();if($('#query').value)p.set('q',$('#query').value);for(const key of fields){const value=$(`[data-filter="${key}"]`)?.value;if(value)p.set(key,value)}if(page>1)p.set('page',String(page));history.replaceState(null,'',location.pathname+(p.size?'?'+p.toString():''))}
function render(){if(!$('#results'))return;const rows=filtered(),pages=Math.ceil(rows.length/pageSize);page=Math.max(1,Math.min(page,pages||1));$('#result-count').textContent=`${rows.length} ressource${rows.length!==1?'s':''} · page ${page} / ${pages||1}`;$('#results').innerHTML=rows.length?rows.slice((page-1)*pageSize,page*pageSize).map(card).join(''):`<div class="empty"><h2>${baseType==='favorite'&&!favorites.size?'Votre bibliothèque personnelle commence ici.':'Aucune ressource pour ces critères.'}</h2><p>${baseType==='favorite'&&!favorites.size?'Ajoutez une fiche avec son bouton de favori.':'Essayez un autre mot ou retirez un filtre.'}</p><a class="btn secondary" href="/bibliotheque/">Explorer toutes les ressources</a></div>`;$('#pagination').innerHTML=pages>1?`<button class="btn secondary" id="prev-page" ${page<=1?'disabled':''}>← Précédente</button><span>${page} / ${pages}</span><button class="btn secondary" id="next-page" ${page>=pages?'disabled':''}>Suivante →</button>`:'';$('#prev-page')?.addEventListener('click',()=>{page--;render();updateURL();$('#result-count').scrollIntoView({block:'center'})});$('#next-page')?.addEventListener('click',()=>{page++;render();updateURL();$('#result-count').scrollIntoView({block:'center'})});syncCompare()}
function orientation(){const form=$('#orientation-form');if(!form)return;const data=Object.fromEntries(new FormData(form));const needMap={'Préparer un cours':['preparation','objectifs'],'Créer une évaluation':['evaluation','qcm'],'Différencier une activité':['differenciation','remediation'],'Créer des supports':['supports','image','video'],'Vérifier un contenu':['verification','recherche'],'Utiliser l’IA avec les élèves':['eleves','integrite']};const words=needMap[data.need]||[];const ranked=catalogue.filter(r=>matchesLevel(r,data.level)&&r.type!=='concept'&&r.type!=='source').map(r=>{let score=r.discipline===data.discipline?4:r.discipline==='Toutes disciplines'?1:0;score+=words.some(w=>norm(r.category+' '+r.title+' '+r.tags.join(' ')).includes(w))?6:0;return {r,score}}).filter(x=>x.score>=6).sort((a,b)=>b.score-a.score);const selected=[];for(const type of ['outil','prompt','tutoriel','scenario','guide']){const item=ranked.find(x=>x.r.type===type);if(item)selected.push(item.r)}$('#orientation-heading').textContent=`Votre sélection : ${data.discipline} · ${data.level}`;$('#orientation-explanation').textContent=`Objectif : ${data.need}. Sélection par objectif et discipline, avec des fiches transversales lorsque le catalogue ne contient pas de fiche spécialisée. Vérifiez l’adaptation à votre classe.`;$('#orientation-results').innerHTML=selected.map(card).join('')||'<p>Aucune sélection disponible. Consultez la bibliothèque.</p>'}
function comparisonView(){if(!$('#comparison'))return;const rows=catalogue.filter(r=>comparison.has(r.id)&&r.type==='outil');if(rows.length<2){$('#comparison').innerHTML='<div class="empty"><h2>Sélectionnez au moins deux outils.</h2><p>Cochez « Comparer cet outil » dans l’annuaire. Votre sélection reste dans ce navigateur.</p></div>';return}const attributes=[['Usage','desc'],['Exemple pédagogique','example'],['Coût / accès','cost'],['Compte','account'],['Langues','language'],['Limites','limits'],['Données','privacy'],['Vérification','verification']];$('#comparison').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Critère</th>${rows.map(r=>`<th><a href="/ressources/${r.id}/">${E(r.title)}</a></th>`).join('')}</tr></thead><tbody>${attributes.map(([label,key])=>`<tr><th>${label}</th>${rows.map(r=>`<td>${E(Array.isArray(r[key])?r[key].join(' '):r[key]||'À vérifier')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function historyView(){if($('#history-results')){const rows=array('history').map(id=>catalogue.find(r=>r.id===id)).filter(Boolean);$('#history-results').innerHTML=rows.length?rows.map(card).join(''):'<p class="empty">Aucune fiche consultée dans ce navigateur.</p>'}}
$('#clear-comparison')?.addEventListener('click',()=>{if(set('comparison',[])){comparison.clear();comparisonView();toast('Sélection effacée.')}});
$('#clear-history')?.addEventListener('click',()=>{if(set('history',[])){historyView();toast('Historique effacé.')}});
$('#orientation-form')?.addEventListener('submit',e=>{e.preventDefault();orientation()});
$('#export-favorites')?.addEventListener('click',()=>{const rows=catalogue.filter(r=>favorites.has(r.id)).map(r=>({id:r.id,titre:r.title,type:names[r.type],url:location.origin+'/ressources/'+r.id+'/'}));download({exporteLe:new Date().toISOString(),ressources:rows},'mes-favoris-manar.json');toast('Favoris préparés pour téléchargement.')});
syncFavorites();
if($('#catalogue')||$('#comparison')||$('#history-results')||$('#orientation-form'))fetch('/catalogue.json').then(r=>{if(!r.ok)throw Error('catalogue');return r.json()}).then(data=>{catalogue=data;if($('#catalogue')){for(const key of fields){const field=$(`[data-filter="${key}"]`);if(field&&params.has(key))field.value=params.get(key)}$('#query').value=params.get('q')||'';page=Math.max(1,parseInt(params.get('page')||'1',10)||1);if(baseType&&baseType!=='favorite'){$('[data-filter="type"]').value='';$('[data-filter="type"]').closest('label').hidden=true}render();$('#filters-form').addEventListener('submit',e=>{e.preventDefault();page=1;render();updateURL()});$('#query').addEventListener('input',()=>{page=1;render();updateURL()});for(const s of $$('[data-filter]'))s.addEventListener('change',()=>{page=1;render();updateURL()});$('#filters-form').addEventListener('reset',()=>setTimeout(()=>{const extra=$('#page-search-results');if(extra)extra.textContent='';page=1;render();updateURL()},0))}comparisonView();historyView();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tool={name:'rechercher_ressources',title:'Rechercher dans SCOLAR·IA',description:'Rechercher les ressources du portail sans modifier les données personnelles.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw Error('Une recherche de 200 caractères maximum est attendue.');return {ressources:catalogue.filter(r=>searchTerms(r,input.query)).slice(0,10).map(r=>({id:r.id,title:r.title,type:r.type,url:'/ressources/'+r.id+'/'}))}}};try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
}).catch(()=>{if($('#result-count'))$('#result-count').textContent='Recherche indisponible. Les fiches restent accessibles dans l’index complet.';if($('#orientation-explanation'))$('#orientation-explanation').textContent='Le catalogue n’a pas pu être chargé. Rechargez la page ou consultez la bibliothèque.';if($('#comparison'))$('#comparison').innerHTML='<p>Catalogue indisponible. Rechargez la page.</p>'});
})();
